fn multi_year_leap_chunks_have_no_overlap_and_no_2012_cutoff() {
    let dates: BTreeSet<_> = generate_calendar_days("2010-01-01", "2013-01-04")
        .unwrap()
        .into_iter()
        .collect();
    let chunks = requests("NIFTY", &dates).unwrap();
