        symbols: &["NIFTYAUTO", "CNXAUTO"],
    },
    IndexAliasFamily {
        canonical: "FINNIFTY",
        symbols: &[
            "FINNIFTY",
            "NIFTYFINSERVICE",
            "NIFTYFINANCIALSERVICE",
use super::*;
use chrono::NaiveDate;

pub(super) fn augment_index_alias_context(
    connection: &Connection,
    mut context: ResolvedInstrumentContext,
) -> AppResult<ResolvedInstrumentContext> {
    if context.exchange != "NSE_INDEX" {
        return Ok(context);
    }
    let Some(family) = nse_index_alias_family(&context.current_symbol) else {
        return Ok(context);
    };
    context.current_symbol = family.canonical.to_string();
    context.resolved_from_alias |= context.requested_symbol != family.canonical;
    if let Some(instrument) =
        find_instrument_record(connection, family.canonical, &context.exchange)?
    {
        context.current_name = instrument.name.clone();
        context.current_instrument = Some(instrument);
    }
    for symbol in family.symbols {
        if !context
            .related_symbols
            .iter()
            .any(|existing| existing == symbol)
        {
            context.related_symbols.push(symbol.to_string());
        }
    }
    context.corporate_actions = load_corporate_actions(
        connection,
        &context.exchange,
        &context.related_symbols,
        context.isin.as_deref(),
    )?;
    Ok(context)
}

pub(super) fn resolve_index_alias_context(
    connection: &Connection,
    requested_symbol: &str,
    exchange: &str,
) -> AppResult<Option<ResolvedInstrumentContext>> {
    let family = nse_index_alias_family(requested_symbol)
        .ok_or_else(|| "Unknown NSE index alias family".to_string())?;
    let mut instrument = None;
    // Prefer canonical metadata, but allow legacy-only databases. File lookup
    // includes every explicit alias even when its instrument row is absent.
    for symbol in family.symbols {
        if let Some(found) = find_instrument_record(connection, symbol, exchange)? {
            instrument = Some(found);
            break;
        }
    }
    let Some(instrument) = instrument else {
        return Ok(None);
    };
    let related_symbols = family
        .symbols
        .iter()
        .map(|value| value.to_string())
        .collect::<Vec<_>>();
    let corporate_actions = load_corporate_actions(connection, exchange, &related_symbols, None)?;
    Ok(Some(ResolvedInstrumentContext {
            .unwrap_or_else(|| vec![symbol.as_str()]);
        for alias in aliases {
            // The full filename owns the identity; never use the truncated header
            // as a lookup key (different long names can share all 32 bytes).
            if alias.is_empty() || !alias.bytes().all(|b| b.is_ascii_alphanumeric()) {
                return Err(format!("Invalid existing index filename identity: {alias}"));
            }
            let path = root.join("eod_data/NSE_INDEX").join(format!("{alias}.eod"));
            // Hybrid databases can contain binary history absent from SQLite.
            // Check both representations before deciding a date is a gap.
            if path.exists() {
                let file = BinaryEodFile::open(&path)?;
                // write_all stores the first 32 bytes, retaining the full filename.
                // Truncated identities additionally require their exact metadata owner.
                let header_symbol = &alias[..alias.len().min(32)];
                let owned = alias.len() <= 32 || connection.query_row(
                    "SELECT EXISTS(SELECT 1 FROM instruments WHERE symbol=?1 COLLATE BINARY AND exchange='NSE_INDEX')",
                    [alias], |r| r.get::<_, bool>(0),
                ).map_err(|e| e.to_string())?;
                if file.header.symbol != header_symbol
                    || !owned
                    || file.header.exchange != "NSE_INDEX"
                    || file.header.price_scale == 0
                {
                    return Err(format!(
                        "Existing index identity/scale mismatch: {}",
                        path.display()
                    ));
                }
                for r in file.read_range(date_to_u32(from), date_to_u32(to))? {
                    let p = [r.open, r.high, r.low, r.close]
                        .map(|v| v as f64 / file.header.price_scale as f64);
                    if !valid_prices(p) {
                        return Err(format!("Invalid existing index OHLC: {alias}@{}", r.date));
                    }
                    existing
                        .entry((symbol.clone(), u32_to_date(r.date)))
                        .or_default()
                        .push((scaled(p), r.volume));
                }
            }
            if !binary {
                let mut stmt = connection.prepare("SELECT date, open, high, low, close, volume FROM eod_prices WHERE exchange='NSE_INDEX' AND symbol=?1 AND date BETWEEN ?2 AND ?3").map_err(|e| e.to_string())?;
