fn json_row(name: &str, date: &str, close: f64) -> serde_json::Value {
    serde_json::json!({"EOD_INDEX_NAME": name, "EOD_TIMESTAMP": date,
        "EOD_OPEN_INDEX_VAL": 100.0, "EOD_HIGH_INDEX_VAL": 110.0,
        "EOD_LOW_INDEX_VAL": 90.0, "EOD_CLOSE_INDEX_VAL": close, "HIT_TRADED_QTY": null})
}
fn payload(rows: Vec<serde_json::Value>) -> Vec<u8> {
    serde_json::to_vec(&serde_json::json!({"data": rows})).unwrap()
}
fn config() -> BatchDownloadConfig {
    BatchDownloadConfig {
        mode: DownloadMode::Range,
        exchanges: ExchangeSelection {
            nse: false,
            bse: false,
            nse_index: true,
            bse_index: false,
        },
}

pub(super) fn requests(symbol: &str, dates: &BTreeSet<String>) -> AppResult<Vec<Request>> {
    let index = SUPPORTED
        .iter()
        .find(|i| i.symbol == symbol)
        .ok_or("Unsupported index")?;
    let mut pending = dates.iter().peekable();
    let mut result = Vec::new();
    while let Some(start) = pending.next() {
        let end = parse_trade_date(start)?
            .checked_add_signed(Duration::days(365))
            .ok_or("Date overflow")?;
        let mut selected = BTreeSet::from([start.clone()]);
        while let Some(date) = pending.peek() {
            if parse_trade_date(date)? > end {
                break;
            }
            selected.insert((*date).clone());
